import gymnasium as gym
import numpy as np
from gymnasium import spaces

class GridDeliveryEnv(gym.Env):
    def __init__(self, grid_size=5):
        super().__init__()
        self.grid_size = grid_size
        self.action_space = spaces.Discrete(4)  # up, down, left, right
        self.observation_space = spaces.Box(0, grid_size - 1, shape=(2,), dtype=np.int32)
        self.goal = np.array([grid_size - 1, grid_size - 1])

    def reset(self, seed=None, options=None):
        super().reset(seed=seed)
        self.pos = np.array([0, 0])
        return self.pos.copy(), {}

    def step(self, action):
        prev_dist = np.linalg.norm(self.pos - self.goal)
        moves = {0: (-1, 0), 1: (1, 0), 2: (0, -1), 3: (0, 1)}
        dx, dy = moves[action]
        self.pos = np.clip(self.pos + [dx, dy], 0, self.grid_size - 1)
        new_dist = np.linalg.norm(self.pos - self.goal)
        reward = (prev_dist - new_dist) - 0.01  # shaped: closer = positive, step cost
        terminated = np.array_equal(self.pos, self.goal)
        if terminated:
            reward += 10.0
        return self.pos.copy(), reward, terminated, False, {}

from collections import defaultdict

def get_pair_counts(word_freqs):
    pairs = defaultdict(int)
    for word, freq in word_freqs.items():
        symbols = word.split()
        for i in range(len(symbols) - 1):
            pairs[(symbols[i], symbols[i + 1])] += freq
    return pairs

def merge_pair(pair, word_freqs):
    new_word_freqs = {}
    bigram = ' '.join(pair)
    replacement = ''.join(pair)
    for word, freq in word_freqs.items():
        new_word = word.replace(bigram, replacement)
        new_word_freqs[new_word] = freq
    return new_word_freqs

def train_bpe(word_freqs, num_merges):
    merges = []
    for _ in range(num_merges):
        pairs = get_pair_counts(word_freqs)
        if not pairs:
            break
        best_pair = max(pairs, key=pairs.get)
        word_freqs = merge_pair(best_pair, word_freqs)
        merges.append(best_pair)
    return merges, word_freqs

import torch
from torch.utils.checkpoint import checkpoint

class CheckpointedTransformer(torch.nn.Module):
    def __init__(self, blocks):
        super().__init__()
        self.blocks = torch.nn.ModuleList(blocks)

    def forward(self, x, use_checkpoint=True):
        for block in self.blocks:
            if use_checkpoint and self.training:
                x = checkpoint(block, x, use_reentrant=False)
            else:
                x = block(x)
        return x

import sqlite3

def execution_correctness_reward(generated_sql, gold_sql, db_path, timeout=5):
    def run_query(sql, conn):
        try:
            cur = conn.cursor()
            cur.execute(sql)
            rows = cur.fetchall()
            return set(map(tuple, rows))
        except Exception:
            return None

    conn = sqlite3.connect(db_path, timeout=timeout)
    try:
        gen_result = run_query(generated_sql, conn)
        gold_result = run_query(gold_sql, conn)
    finally:
        conn.close()

    if gen_result is None:
        return -1.0  # invalid/failed SQL
    if gold_result is None:
        raise ValueError("Gold query itself failed to execute")
    if gen_result == gold_result:
        return 1.0
    return -0.3  # valid SQL, wrong result
